<script setup lang="ts">
const { data } = await useWorkspace()
const left = ref(''), right = ref(''), results = ref<any[]>([]), busy = ref(false), error = ref('')
const keys = ['epochs', 'batch', 'accum', 'lr', 'rank', 'evalFrac', 'seed']
const metricKeys = ['eval_loss', 'eval_cer', 'eval_wer', 'eval_tamil_wer', 'eval_latin_wer', 'eval_script_confusion']
async function compare() { busy.value = true; error.value = ''; try { results.value = await Promise.all([left.value, right.value].map(id => $fetch(`/api/runs/${id}`))) } catch (e) { error.value = apiError(e) } finally { busy.value = false } }
function metric(result: any, key: string) { const value = result.metrics.filter((m: any) => typeof m.payload[key] === 'number').at(-1)?.payload[key]; return value === undefined ? '—' : key === 'eval_loss' ? value.toFixed(4) : `${(value * 100).toFixed(2)}%` }
</script>
<template><NuxtLink to="/runs" class="back-link"><AppIcon name="ArrowLeft" :size="16" />Experiments</NuxtLink><div class="page-heading"><div><span class="eyebrow">FIND WHAT CHANGED</span><h1>Compare experiments<span class="title-dot">.</span></h1><p>Put configurations and the latest evaluation results side by side.</p></div></div><form class="panel comparison-select" @submit.prevent="compare"><label class="field">Experiment A<select v-model="left" required><option value="" disabled>Select an experiment</option><option v-for="run in data.runs" :key="run.id" :value="run.id">{{ run.name }}</option></select></label><label class="field">Experiment B<select v-model="right" required><option value="" disabled>Select an experiment</option><option v-for="run in data.runs" :key="run.id" :value="run.id">{{ run.name }}</option></select></label><button class="button primary" :disabled="busy || !left || !right || left === right">Compare<AppIcon name="GitBranch" :size="16" /></button></form><p v-if="error" class="alert error">{{ error }}</p><template v-if="results.length === 2"><div class="alert info">Only compare quality on the same evaluation data and normalization rules. Different splits or label sources can make scores incomparable.</div><section class="panel table-scroll"><table><thead><tr><th>Configuration / metric</th><th v-for="result in results" :key="result.run.id">{{ result.run.name }}</th></tr></thead><tbody><tr><td>Dataset</td><td v-for="result in results" :key="result.run.id">{{ result.run.snapshot.dataset.name }}</td></tr><tr><td>Model</td><td v-for="result in results" :key="result.run.id">{{ result.run.snapshot.model.name }}</td></tr><tr v-for="key in keys" :key="key"><td>{{ key }}</td><td v-for="result in results" :key="result.run.id" class="mono">{{ result.run.config[key] }}</td></tr><tr v-for="key in metricKeys" :key="key"><td>{{ key.replaceAll('_', ' ') }}</td><td v-for="result in results" :key="result.run.id" class="mono">{{ metric(result, key) }}</td></tr></tbody></table></section><div class="chart-grid bottom-info"><MetricChart v-for="result in results" :key="result.run.id" :events="result.metrics" :title="result.run.name" /></div></template><section v-else class="panel"><EmptyState icon="GitBranch" title="Two runs. A clearer picture." description="Choose two experiments to understand how parameter changes affected training." /></section></template>
